"""A headless terminal emulator backed by a real PTY and an interactive bash.

Usage:
    from headless_terminal import HeadlessTerminal

    term = HeadlessTerminal()
    term.send_keystrokes("echo hello\n", wait_sec=1)
    print(term.get_screen())
    term.close()
"""

from __future__ import annotations

import fcntl
import os
import pty
import re
import shutil
import signal
import struct
import termios
import threading
import time
from typing import List, Optional, Sequence

import pyte

from base_terminal import BaseTerminal

_DEFAULT_COLUMNS = 120
_DEFAULT_LINES = 40


class HeadlessTerminal(BaseTerminal):
    """Runs an interactive shell inside a pseudo-terminal.

    The shell is started as an interactive process attached to a PTY, so it
    sources the usual startup files (``~/.bashrc`` and friends) and behaves
    exactly like a terminal for interactive programs (vim, top, python, ...).
    Output is rendered through a VT100-compatible screen emulator, so the
    visible screen contents can be inspected at any time.
    """

    def __init__(
        self,
        command: Optional[Sequence[str]] = None,
        columns: int = _DEFAULT_COLUMNS,
        lines: int = _DEFAULT_LINES,
        cwd: Optional[str] = None,
        env: Optional[dict] = None,
        history: int = 2000,
    ) -> None:
        self.columns = int(columns)
        self.lines = int(lines)

        self._screen = pyte.HistoryScreen(self.columns, self.lines, history=history, ratio=0.5)
        self._screen.set_mode(pyte.modes.LNM)
        self._stream = pyte.ByteStream(self._screen)

        self._raw = bytearray()
        self._lock = threading.RLock()
        self._closed = False

        argv = list(command) if command else self._default_shell_argv()
        child_env = self._build_env(env)

        pid, fd = pty.fork()
        if pid == 0:  # child
            try:
                if cwd:
                    os.chdir(cwd)
                os.execvpe(argv[0], argv, child_env)
            except Exception:
                os._exit(127)

        self.pid = pid
        self.fd = fd
        self._set_winsize(self.lines, self.columns)

        self._reader = threading.Thread(target=self._read_loop, daemon=True)
        self._reader.start()

        # Give the shell a moment to start up and print its first prompt.
        self._wait_for_startup()

    # ------------------------------------------------------------------ setup

    @staticmethod
    def _default_shell_argv() -> List[str]:
        shell = shutil.which("bash") or os.environ.get("SHELL") or shutil.which("sh") or "/bin/sh"
        # ``-i`` forces an interactive shell, which sources ~/.bashrc.
        return [shell, "-i"]

    def _build_env(self, env: Optional[dict]) -> dict:
        child_env = dict(os.environ if env is None else env)
        child_env.setdefault("TERM", "xterm-256color")
        child_env["COLUMNS"] = str(self.columns)
        child_env["LINES"] = str(self.lines)
        # Avoid pagers hijacking the screen in ways tests cannot dismiss.
        child_env.setdefault("PAGER", "cat")
        return child_env

    def _set_winsize(self, rows: int, cols: int) -> None:
        try:
            fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        except OSError:
            pass

    def _wait_for_startup(self, timeout: float = 5.0) -> None:
        deadline = time.time() + timeout
        while time.time() < deadline:
            time.sleep(0.05)
            with self._lock:
                if self._raw:
                    break
        # Let the prompt settle.
        time.sleep(0.2)

    # ------------------------------------------------------------------- io

    def _read_loop(self) -> None:
        while True:
            try:
                data = os.read(self.fd, 65536)
            except (OSError, ValueError):
                break
            if not data:
                break
            with self._lock:
                self._raw.extend(data)
                try:
                    self._stream.feed(data)
                except Exception:
                    pass
        self._closed = True

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Sends keystrokes to the terminal.

        Args:
            keystrokes: The keystrokes to send to the terminal.
            wait_sec: The number of seconds to wait for the command to complete.
        """
        if isinstance(keystrokes, bytes):
            data = keystrokes
        else:
            data = str(keystrokes).encode("utf-8", errors="replace")

        while data:
            try:
                written = os.write(self.fd, data)
            except OSError:
                break
            data = data[written:]

        if wait_sec and wait_sec > 0:
            time.sleep(wait_sec)

    # Convenient aliases.
    send = send_keys = type_keys = write = send_keystrokes

    # --------------------------------------------------------------- capture

    def get_screen(self) -> str:
        """Returns the currently visible screen contents as text."""
        with self._lock:
            display = list(self._screen.display)
        return "\n".join(line.rstrip() for line in display).rstrip("\n")

    # Common alternative spellings used by callers/tests.
    capture_pane = capture = screen = read_screen = get_screen_contents = get_screen

    def get_screen_lines(self) -> List[str]:
        with self._lock:
            return [line.rstrip() for line in self._screen.display]

    def get_raw_output(self) -> str:
        """Returns everything the process has written, escape codes included."""
        with self._lock:
            return self._raw.decode("utf-8", errors="replace")

    def get_output(self) -> str:
        """Returns everything the process has written, with escape codes stripped."""
        return self._strip_ansi(self.get_raw_output())

    output = get_output

    def get_history(self) -> str:
        """Returns scrollback (if any) plus the visible screen."""
        with self._lock:
            top = [
                "".join(char.data for char in sorted(line.values(), key=lambda c: 0) or [])
                for line in []
            ]
            history_lines = []
            for line in self._screen.history.top:
                history_lines.append(self._render_history_line(line))
            display = list(self._screen.display)
        lines = [l.rstrip() for l in history_lines + display]
        while lines and not lines[-1]:
            lines.pop()
        return "\n".join(lines)

    def _render_history_line(self, line) -> str:
        try:
            return "".join(line[x].data for x in range(self.columns))
        except Exception:
            try:
                return "".join(char.data for char in line.values())
            except Exception:
                return ""

    @staticmethod
    def _strip_ansi(text: str) -> str:
        text = re.sub(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", "", text)
        text = re.sub(r"\x1b[@-Z\\-_]|\x1b\[[0-?]*[ -/]*[@-~]", "", text)
        return text.replace("\r\n", "\n")

    def clear_screen(self) -> None:
        with self._lock:
            self._screen.reset()
            self._raw.clear()

    def wait(self, seconds: float) -> None:
        time.sleep(seconds)

    def wait_for(self, pattern: str, timeout: float = 10.0, interval: float = 0.1) -> bool:
        """Waits until ``pattern`` (a regex or literal) shows up on screen."""
        deadline = time.time() + timeout
        try:
            regex = re.compile(pattern)
        except re.error:
            regex = None
        while time.time() < deadline:
            screen = self.get_screen()
            if (regex.search(screen) if regex is not None else pattern in screen):
                return True
            time.sleep(interval)
        return False

    # ------------------------------------------------------------- lifecycle

    @property
    def is_alive(self) -> bool:
        try:
            pid, _ = os.waitpid(self.pid, os.WNOHANG)
        except (ChildProcessError, OSError):
            return False
        return pid == 0

    def close(self, timeout: float = 2.0) -> None:
        """Terminates the shell and releases the PTY."""
        if getattr(self, "_shutdown", False):
            return
        self._shutdown = True
        for sig in (signal.SIGHUP, signal.SIGKILL):
            try:
                os.kill(self.pid, sig)
            except (ProcessLookupError, OSError):
                break
            deadline = time.time() + timeout
            while time.time() < deadline:
                try:
                    pid, _ = os.waitpid(self.pid, os.WNOHANG)
                except (ChildProcessError, OSError):
                    pid = self.pid
                if pid != 0:
                    break
                time.sleep(0.05)
            else:
                continue
            break
        try:
            os.close(self.fd)
        except OSError:
            pass

    stop = kill = terminate = quit = close

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass

    def __str__(self) -> str:
        return self.get_screen()
